// CSD_RATIONALE_BEGIN
// Root-cause analysis for attempts 35/36 (38.8% accuracy, 87.8% syntax):
//
// Attempt 35 used trigger `closeCount == 0 || openCount > closeCount || braceInTail`.
//   The extra triggers caused Phase 3 to fire for examples where the model had
//   ALREADY produced a CORRECT `<<A>>` span, replacing it with a wrong constrained
//   expression `<<B>>`. This is the documented −10.2pp accuracy drop.
//
// Attempt 36 fixed triggers to `closeCount == 0` only, but for `openCount > 0`
//   cases used `EnterObservedConstrainedSpan`. This is broken: the model's partial
//   `<<int(n * s + k_2 * n * s + ...` is in `generated`, but `currentConstrained = []`.
//   `CloseSpanWithinBudget` sees empty currentConstrained and generates a fresh
//   sub-expression (e.g., `int(x)>>`), appending it AFTER the partial to produce
//   `<<int(n * s + ... int(x)>>`, which is syntactically invalid and confuses the
//   evaluator. This caused the 2 `final_span_unclosed` and mode_C failures.
//
// Attempt 34 (49% accuracy, best) used `OpenConstrainedSpan` for ALL Phase 3 cases.
//   When model writes `<<...` (partial, no `>>`): `OpenConstrainedSpan` appends a
//   new `<<`, then `CloseSpanWithinBudget` generates `int(expr)>>`. Result:
//   `...<<partial...<<int(expr)>>`. Evaluator extracts LAST complete `<< >>` =
//   `<<int(expr)>>` which is at least syntactically valid.
//
// Attempt 37 strategy (to match attempt 34):
//   Phase 3 trigger: `closeCount == 0` only (no openCount > closeCount, no braceInTail).
//   Phase 3 execution: ALWAYS `OpenConstrainedSpan` (never EnterObservedConstrainedSpan).
//   This ensures the 2 unclosed examples convert from "no valid span" to "valid span"
//   (improving syntax from 87.8% → ~91.8%), while the aggressive triggers that
//   corrupted correct examples in attempt 35 are absent.
//
// Expected: accuracy ≥ 44.9% (matches attempt 34 ~49%), syntax ≥ 90.0%.
// Budget: phase1Budget = maxSteps − 51, Phase 3 = 1 (open) + 50 (close) ≤ maxSteps.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   if-branch (insideConstrained on entry):
//     CloseSpanWithinBudget postcondition directly provides
//     `insideOut ==> parser.IsValidPrefix(currentOut)`. When it closes the span,
//     insideConstrainedOut = false (antecedent vacuously false). When it leaves
//     the span open, the postcondition gives validity directly. ✓
//
//   else-branch Phase 1 loop:
//     The loop invariant `!insideConstrainedOut` is maintained throughout (never
//     modified in the body; only UnconstrainedStep + append). The implication
//     `false ==> ...` is vacuously true every iteration. ✓
//
//   else-branch Phase 3 fires (closeCount == 0 && steps < maxSteps):
//     OpenConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//     `parser.IsValidPrefix([])` holds by method precondition. Then
//     CloseSpanWithinBudget postcondition provides `insideOut ==> parser.IsValidPrefix(currentOut)`
//     for the returned state. ✓
//
//   else-branch Phase 3 skipped (closeCount > 0 or budget exhausted):
//     insideConstrainedOut remains false; implication vacuously true. ✓
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   if-branch: CloseSpanWithinBudget ensures |cg0| <= |generated| + budget0.
//     steps := budget0 <= maxSteps. |generated| <= |generatedPrefix| + budget0 = steps_end. ✓
//
//   Phase 1 loop initialization: |generated| = |generatedPrefix|, steps = 0. ✓
//     EOS break: generated unchanged, steps incremented → bound still holds.
//     Non-EOS: generated grows by 1, steps grows by 1 → |generated| = |generatedPrefix| + steps. ✓
//
//   Phase 3 OpenConstrainedSpan: appends exactly `<<` (+1 token), steps += 1. Balanced. ✓
//   Phase 3 CloseSpanWithinBudget: |generated| grows by at most budget3, steps += budget3.
//     EOS and rejected suffix tokens inside CloseSpanWithinBudget consume step budget
//     without visible output growth, preserving the length bound. ✓
//
//   Budget bound for cost <= maxSteps:
//     maxSteps > spanBudget + 1: phase1Budget + 1 + budget3 <= (maxSteps-51) + 1 + 50 = maxSteps. ✓
//     maxSteps <= spanBudget + 1: phase1Budget = maxSteps; if Phase 3 fires,
//       steps_after_open = steps_p1 + 1 <= maxSteps; budget3 = maxSteps - steps_after_open;
//       total = steps_after_open + budget3 = maxSteps. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. " +
    "Write the FINAL answer as <<int(expr)>> using PLAIN variable names - " +
    "NO curly braces (write n not {n}, write price not {price}). " +
    "Do NOT use ** for exponentiation. " +
    "Allowed operators only: +, -, *, /, //, (, ), int(). " +
    "Example: <<int(n * price - discount)>>");

  var spanBudget: nat := 50;
  var steps: nat := 0;

  if insideConstrainedOut {
    // Entry with an already-open constrained span: close it within budget.
    if steps < maxSteps {
      var remaining0: nat := maxSteps - steps;
      var budget0: nat;
      if remaining0 < spanBudget {
        budget0 := remaining0;
      } else {
        budget0 := spanBudget;
      }
      var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget0
      );
      generated := cg0;
      insideConstrainedOut := ci0;
      currentConstrainedOut := cc0;
      steps := steps + budget0;
    }
  } else {
    // Phase 1: Full unconstrained generation — let the model reason and write <<int(expr)>> naturally.
    var phase1Budget: nat;
    if maxSteps > spanBudget + 1 {
      phase1Budget := maxSteps - spanBudget - 1;
    } else {
      phase1Budget := maxSteps;
    }

    while steps < phase1Budget
      invariant 0 <= steps <= phase1Budget
      invariant phase1Budget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase1Budget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Phase 3: Intervene only when there are NO complete visible spans.
    // When closeCount > 0, the evaluator uses the last complete span (may be correct).
    // Don't trigger on openCount > closeCount or braceInTail — those triggers caused
    // incorrect Phase 3 firing on examples with correct natural spans in attempt 35.
    var generatedStr := CSDHelpers.PrefixToString(generated);
    var closeCount := CSDHelpers.CountSubstring(generatedStr, ">>");

    if closeCount == 0 && steps < maxSteps {
      // Always use OpenConstrainedSpan (fresh <<) regardless of whether model already
      // wrote a partial <<. This appends a new << so CloseSpanWithinBudget generates
      // a complete <<int(expr)>> that becomes the last visible span the evaluator extracts.
      // This is correct for both openCount == 0 (no span) and openCount > 0 (partial span).
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;

      if insideConstrainedOut && steps < maxSteps {
        var remaining3: nat := maxSteps - steps;
        var budget3: nat;
        if remaining3 < spanBudget {
          budget3 := remaining3;
        } else {
          budget3 := spanBudget;
        }
        var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
        );
        generated := cg3;
        insideConstrainedOut := ci3;
        currentConstrainedOut := cc3;
        steps := steps + budget3;
      }
    }
  }

  cost := steps;

